  const [ls, ms] = await Promise.all([C('prd_listings').where('status', '==', '판매중').select('listingId', 'bookId', 'grade', 'active', 'title').get(), C('prd_book_metrics').select('salesPoint').get()]); const SP = new Map(); ms.forEach((d) => { const x = (d.data() || {}).salesPoint; if (x != null && x !== '' && !isNaN(+x)) SP.set(d.id, +x); });
