  const need = [...cand.A, ...cand.B, ...cand.C, ...cand.D]; const NOTE = new Map(); for (let i = 0; i < need.length; i += 300) { const refs = need.slice(i, i + 300).map((x) => C('prd_used_info').doc(x.lid)); try { const sn = await db.getAll(...refs, { fieldMask: ['note'] }); sn.forEach((s) => { if (s.exists) NOTE.set(s.id, realNote((s.data() || {}).note, null) ? 1 : 0); }); } catch (e) {} }
  const shuf = (a) => { for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };
