    const want = new Map(); let nL = 0, nSold = 0; (await C('prd_listings').select('bookId', 'isbn13', 'status', 'active').get()).forEach((d) => { const v = d.data() || {}; nL++; const k = v.bookId || (v.isbn13 ? 'isbn:' + v.isbn13 : null); if (!k || mt.has(k) || have.has(k) || want.has(k)) return; if (!v.active) nSold++; want.set(k, { k, bid: v.bookId || null, isbn: v.isbn13 || null }); });
    const bids = [...want.values()].filter((x) => x.bid).map((x) => x.bid); for (let i = 0; i < bids.length; i += 300) { const got = await db.getAll(...bids.slice(i, i + 300).map((b) => C('prd_books').doc(b)), { fieldMask: ['aladinItemId', 'isbn13'] }); got.forEach((d) => { const x = want.get(d.id); if (x && d.exists) { const v = d.data(); x.iid = v.aladinItemId ? String(v.aladinItemId) : null; x.isbn = x.isbn || v.isbn13 || null; } }); }
