  if (u.email_verified === false) throw Object.assign(new Error('이메일 확인이 안 된 계정'), { code: 403 }); /* (0.11.0) 확인 안 된 이메일로 남의 주소를 쓰지 못하게 */
  const em = String(u.email || '').toLowerCase(); if (!ALLOW.includes(em) && !(await allowDyn()).has(em)) throw Object.assign(new Error('허용되지 않은 계정: ' + u.email), { code: 403 }); return u;
