const keyOk = (req) => { if (!TICK_KEY) return false; const a = Buffer.from(String(req.headers['x-tick-key'] || '')), b = Buffer.from(TICK_KEY); return a.length === b.length && require('crypto').timingSafeEqual(a, b); }; /* (0.11.0) 같은 시간으로 비교 */
