  ls.forEach((d) => { const v = d.data() || {}; const r = String(v.registeredAt || '').slice(0, 10); if (!(r >= from && r <= to) || !v.bookId) return; L.push({ b: v.bookId, sold: !v.active && /판매완료/.test(String(v.status || '')) ? 1 : 0, r, price: +v.price || null, grade: v.grade || null }); need.add(v.bookId); });
